const VAULT = process.env.VAULT ?? "testVault";

export const connect = async () => {
  const targets = await (await fetch("http://127.0.0.1:9222/json/list")).json();
  const pages = targets.filter((t) => t.type === "page");

  for (const t of pages) {
    const ws = new WebSocket(t.webSocketDebuggerUrl, { maxPayload: 256 * 1024 * 1024 });
    await new Promise((res, rej) => { ws.once("open", res); ws.once("error", rej); });
    const client = makeClient(ws);
    const name = await client.evaluate(
      `(() => { try { return window.app && window.app.vault ? window.app.vault.getName() : null; } catch (e) { return null; } })()`
    );
    if (name === VAULT) return client;
    ws.close();
  }
  throw new Error(`no page target for vault ${VAULT}`);
};

const makeClient = (ws) => {
  let id = 0;
  const pending = new Map();
  ws.on("message", (raw) => {
    const msg = JSON.parse(raw.toString());
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
    }
  });

  const send = (method, params = {}) =>
    new Promise((resolve, reject) => {
      const msgId = ++id;
      pending.set(msgId, { resolve, reject });
      ws.send(JSON.stringify({ id: msgId, method, params }));
    });

  const evaluate = async (expression) => {
    const r = await send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
      userGesture: true,
    });
    if (r.exceptionDetails) {
      throw new Error(
        r.exceptionDetails.exception?.description ??
          JSON.stringify(r.exceptionDetails)
      );
    }
    return r.result.value;
  };

  const waitFor = async (expression, { timeout = 8000, label = expression } = {}) => {
    const deadline = Date.now() + timeout;
    let last;
    while (Date.now() < deadline) {
      last = await evaluate(`(() => { try { return (${expression}); } catch (e) { return null; } })()`);
      if (last) return last;
      await new Promise((r) => setTimeout(r, 25));
    }
    throw new Error(`waitFor timed out: ${label} (last=${JSON.stringify(last)})`);
  };

  return { send, evaluate, waitFor, close: () => ws.close() };
};

